func:
// Credentials come from env vars -- never hardcoded.
var base = env.get('PROXMOX_URL');
var tok  = env.get('PROXMOX_TOKEN');
if (!base || !tok) {
  node.status({fill:'red',shape:'ring',text:'missing config'});
  return null;
}
var node = env.get('PROXMOX_NODE') || 'pve';
msg.method = 'GET';
msg.url = base.replace(/\/+$/, '') + '/api2/json/nodes/' + node + '/status';
msg.headers = {};
msg.headers['Authorization'] = 'PVEAPIToken=' + tok;
msg.rejectUnauthorized = false;
return msg;

var d = (msg.payload && msg.payload.data) ? msg.payload.data : null;
if (!d) { node.status({fill:'red',shape:'ring',text:'no data'}); return null; }
var cpu = Math.round((d.cpu || 0) * 1000) / 10;
var memUsed = (d.memory && d.memory.used) || 0;
var memTot = (d.memory && d.memory.total) || 1;
var mem = Math.round(memUsed / memTot * 1000) / 10;
var up = d.uptime || 0;
var days = Math.floor(up / 86400), hrs = Math.floor((up % 86400) / 3600);
node.status({fill:'green',shape:'dot',text:cpu + '% cpu'});
// Human-readable byte formatting for the disk/swap/memory rows.
function gb(v) { return (Math.round(v / 1073741824 * 10) / 10) + ' GB'; }
function pct(u, t) { return t ? Math.round(u / t * 1000) / 10 + '%' : 'n/a'; }
// Nested sub-objects are flattened onto the payload so the Host Detail
// template can reach them with plain dotted paths -- confirmed present in
// the live response by tools/probe_proxmox_status.py.
var rootfs = d.rootfs || {}, swap = d.swap || {};
var mem2 = d.memory || {};
var ci = d.cpuinfo || {}, kd = d['current-kernel'] || {}, la = d.loadavg || [];
var detail = {
  payload: {
    pveversion: d.pveversion || 'unknown',
    kversion: d.kversion || kd.release || 'unknown',
    model: ci.model || 'unknown',
    cores: ci.cores || ci.cpus || '?',
    mhz: ci.mhz || '?',
    load1: (la[0] != null ? Math.round(la[0] * 100) / 100 : '?'),
    load5: (la[1] != null ? Math.round(la[1] * 100) / 100 : '?'),
    load15: (la[2] != null ? Math.round(la[2] * 100) / 100 : '?'),
    uptime: days + 'd ' + hrs + 'h'
  }
};
var mSwap = {payload: pct(swap.used, swap.total) + ' of ' + gb(swap.total || 0)};
var mDisk = {payload: pct(rootfs.used, rootfs.total) + ' of ' + gb(rootfs.total || 0)
  + '  (' + gb(rootfs.avail || 0) + ' free)'};
var mMem  = {payload: gb(mem2.used || 0) + ' of ' + gb(mem2.total || 0)
  + '  (' + gb(mem2.available || 0) + ' avail)'};
var mCpu = {payload: cpu};
var mMemG = {payload: mem};
var mStat = {payload: 'Up ' + days + 'd ' + hrs + 'h' + (d.loadavg ? ' | load ' + (Math.round(d.loadavg[0]*100)/100) : '')};
var mChart = {payload: cpu, topic: 'cpu'};
return [mCpu, mMemG, mStat, mChart, detail, mSwap, mDisk, mMem];
